package payments

type TransactionService struct {
    repo           TransactionRepo
    idempRepo      IdempotencyRepo
    gateway        PaymentGateway // implemented by gateway_adapter.go
    logger         Logger
    config         Config
}

// ProcessTransaction orchestrates: create pending tx row, claim idempotency entry, call gateway, update status.
func (s *TransactionService) ProcessTransaction(ctx context.Context, req *ProcessRequest) (*TransactionResult, error) {
    // propagate correlation ID from ctx; all outgoing calls use ctx
    // validate input earlier (omitted)

    // 1) Ensure idempotency entry (INSERT ... ON CONFLICT RETURNING)
    idemp, err := s.idempRepo.ClaimOrGet(ctx, req.IdempotencyKey, req.CustomerID, s.config.IdempotencyTTL)
    if err != nil {
        s.logger.Warn(ctx, "idempotency claim failed", map[string]interface{}{"err": err})
        return nil, NewApiError("idempotency_error", "failed to create idempotency entry", http.StatusInternalServerError)
    }

    // If there is a stored final result, return it immediately
    if idemp.Status == IdempotencyStatusDone {
        return idemp.Result, nil
    }

    // If entry is IN_PROGRESS started by another caller, wait/poll until result appears or ctx expires
    if idemp.Status == IdempotencyStatusInProgress && !idemp.OwnedByCaller {
        res, err := s.idempRepo.WaitForResult(ctx, idemp.ID, s.config.IdempotencyWaitBackoff)
        if err != nil {
            return nil, NewApiError("idempotency_wait_timeout", "request in progress; try again", http.StatusAccepted)
        }
        return res, nil
    }

    // At this point, caller owns the idempotency entry and should proceed to create a pending transaction row.

    // 2) Insert pending transaction (committed) -> do NOT hold tx across external call
    txRecord := &Transaction{CustomerID: req.CustomerID, AmountCents: req.AmountCents, Currency: req.Currency, Status: StatusPending, CreatedAt: time.Now(), IdempotencyKey: req.IdempotencyKey}
    if err := s.repo.CreatePending(ctx, txRecord); err != nil {
        // mark idempotency entry as failed/clear ownership
        s.idempRepo.MarkFailed(ctx, idemp.ID, err)
        return nil, NewApiError("db_error", "failed to create transaction", http.StatusInternalServerError)
    }

    // 3) Call gateway with ctx-derived timeout (gateway adapter also respects ctx)
    gwReq := GatewayRequestFrom(req, txRecord)
    gwRes, gwErr := s.gateway.Process(ctx, gwReq, WithIdempotencyHeader(req.IdempotencyKey))

    // 4) Short conditional update of transaction status (optimistic update) in a short DB tx
    var finalStatus TransactionStatus
    var clientResult *TransactionResult
    if gwErr == nil && gwRes.Success {
        finalStatus = StatusSucceeded
        clientResult = &TransactionResult{TransactionID: txRecord.ID, Status: string(finalStatus), ProviderID: gwRes.ProviderID}
    } else {
        finalStatus = StatusFailed
        clientResult = &TransactionResult{TransactionID: txRecord.ID, Status: string(finalStatus), ErrorCode: mapGatewayErrorToApiCode(gwErr, gwRes)}
    }

    // Attempt optimistic update: only update if still pending
    updated, err := s.repo.UpdateStatusIfPending(ctx, txRecord.ID, finalStatus, gwRes)
    if err != nil {
        s.logger.Error(ctx, "status update failed", map[string]interface{}{"tx": txRecord.ID, "err": err})
        // do not return internal error to client; return a stable ApiError
        s.idempRepo.MarkFailed(ctx, idemp.ID, err)
        return nil, NewApiError("update_failed", "could not finalize transaction", http.StatusInternalServerError)
    }

    if updated == 0 {
        // race: someone else updated the status; re-fetch current state and return that
        current, rerr := s.repo.GetByID(ctx, txRecord.ID)
        if rerr != nil {
            return nil, NewApiError("read_failed", "could not fetch transaction status", http.StatusInternalServerError)
        }
        // map current to client result
        clientResult = mapTransactionToResult(current)
    }

    // 5) Persist final idempotency result atomically (non-blocking) and return the clientResult
    if err := s.idempRepo.StoreResult(ctx, idemp.ID, clientResult); err != nil {
        s.logger.Warn(ctx, "failed to persist idempotency result", map[string]interface{}{"idemp": idemp.ID, "err": err})
        // do not fail the client; we still return clientResult
    }

    return clientResult, nil
}

--- idempotency_repo.go ---
package payments

// DB table idempotency(id serial pk, idempotency_key text, customer_id text, status text, result jsonb NULL, created_at timestamptz, ttl timestamptz)

// ClaimOrGet attempts to insert an IN_PROGRESS row and returns the canonical row (may be pre-existing).
func (r *pgIdempotencyRepo) ClaimOrGet(ctx context.Context, key, customerID string, ttl time.Duration) (*IdempotencyEntry, error) {
    // TTL expiry timestamp
    expiry := time.Now().Add(ttl)

    // Upsert while returning the canonical row to avoid TOCTOU
    // We set status = 'IN_PROGRESS' on insert; on conflict we do NOT overwrite result/status (only extend ttl)
    query := `
INSERT INTO idempotency (idempotency_key, customer_id, status, created_at, ttl)
VALUES ($1, $2, 'IN_PROGRESS', now(), $3)
ON CONFLICT (idempotency_key, customer_id)
DO UPDATE SET ttl = GREATEST(idempotency.ttl, EXCLUDED.ttl)
RETURNING id, status, result, created_at, ttl
`
    row := r.db.QueryRowContext(ctx, query, key, customerID, expiry)
    var e IdempotencyEntry
    var rawResult sql.NullString
    if err := row.Scan(&e.ID, &e.Status, &rawResult, &e.CreatedAt, &e.TTL); err != nil {
        return nil, err
    }
    if rawResult.Valid {
        _ = json.Unmarshal([]byte(rawResult.String), &e.Result)
    }

    // Determine whether this caller is the owner: if status == IN_PROGRESS and created_at is very recent
    // (This is heuristic; caller will treat IN_PROGRESS by waiting for result. If multiple callers race to INSERT, they all get the same canonical row.)
    e.OwnedByCaller = (e.Status == IdempotencyStatusInProgress && time.Since(e.CreatedAt) < 2*time.Second)
    return &e, nil
}

func (r *pgIdempotencyRepo) WaitForResult(ctx context.Context, id int64, backoffCfg BackoffConfig) (*TransactionResult, error) {
    // poll with exponential-backoff until status != IN_PROGRESS or ctx expires
    attempt := 0
    for {
        select {
        case <-ctx.Done():
            return nil, ctx.Err()
        default:
        }
        row := r.db.QueryRowContext(ctx, `SELECT status, result FROM idempotency WHERE id = $1`, id)
        var status string
        var result sql.NullString
        if err := row.Scan(&status, &result); err != nil {
            return nil, err
        }
        if status == IdempotencyStatusDone && result.Valid {
            var tr TransactionResult
            _ = json.Unmarshal([]byte(result.String), &tr)
            return &tr, nil
        }
        if status == IdempotencyStatusFailed {
            return nil, NewApiError("idempotency_failed", "previous attempt failed", http.StatusConflict)
        }
        // still in progress; sleep with jitter
        attempt++
        sleep := backoffWithJitter(backoffCfg, attempt)
        timer := time.NewTimer(sleep)
        select {
        case <-ctx.Done():
            timer.Stop()
            return nil, ctx.Err()
        case <-timer.C:
        }
    }
}

func (r *pgIdempotencyRepo) StoreResult(ctx context.Context, id int64, result *TransactionResult) error {
    raw, _ := json.Marshal(result)
    // Set status = DONE and persist result only if currently IN_PROGRESS
    query := `UPDATE idempotency SET status = 'DONE', result = $1 WHERE id = $2 AND status = 'IN_PROGRESS'`
    res, err := r.db.ExecContext(ctx, query, raw, id)
    if err != nil {
        return err
    }
    if rows, _ := res.RowsAffected(); rows == 0 {
        // someone else already updated; that's ok
    }
    return nil
}

func (r *pgIdempotencyRepo) MarkFailed(ctx context.Context, id int64, errIn error) {
    // best-effort mark as failed
    raw, _ := json.Marshal(map[string]string{"err": errIn.Error()})
    r.db.ExecContext(ctx, `UPDATE idempotency SET status='FAILED', result=$1 WHERE id=$2 AND status='IN_PROGRESS'`, raw, id)
}

