func (g *gatewayAdapter) Process(ctx context.Context, req *GatewayRequest, opts ...GatewayOption) (*GatewayResult, error) {
    // Respect ctx; derive per-attempt timeout from ctx if configured
    // Use circuit breaker to fast-fail when provider unstable
    if !g.cb.Allow() {
        return nil, NewApiError("gateway_unavailable", "payment provider unavailable (circuit open)", http.StatusServiceUnavailable)
    }

    // forward idempotency header when present
    headers := defaultHeaders()
    if req.IdempotencyKey != "" {
        headers.Set(g.config.IdempotencyHeaderName, req.IdempotencyKey)
    }

    var lastErr error
    attempt := 0
    for attempt < g.config.MaxAttempts {
        attempt++
        // For each try respect ctx deadline; create child ctx with per-attempt timeout
        attemptCtx, cancel := context.WithTimeout(ctx, g.config.AttemptTimeout)
        defer cancel()

        res, err := g.callProvider(attemptCtx, req, headers)
        if err == nil && res != nil && res.Success {
            g.cb.RecordSuccess()
            return res, nil
        }

        // classify error: transient vs permanent
        if isTransientProviderError(err, res) {
            lastErr = err
            g.cb.RecordFailure()
            // backoff with jitter
            sleep := backoffWithJitter(g.config.Backoff, attempt)
            select {
            case <-attemptCtx.Done():
                // respect cancellation
                return nil, attemptCtx.Err()
            case <-time.After(sleep):
                continue
            }
        }

        // permanent error; break and return
        if !isRetryableError(err, res) {
            // record failure and return
            g.cb.RecordFailure()
            return res, err
        }
    }

    // exhausted attempts
    if lastErr != nil {
        return nil, lastErr
    }
    return nil, NewApiError("gateway_error", "payment provider error", http.StatusBadGateway)
}

// callProvider performs the actual HTTP request to the provider and returns parsed GatewayResult
func (g *gatewayAdapter) callProvider(ctx context.Context, req *GatewayRequest, headers http.Header) (*GatewayResult, error) {
    // build request, set headers (incl. idempotency), marshal body
    // perform http request using client that respects ctx
    // parse response; scrub sensitive provider response fields before returning
    // (e.g., only return provider_id, success boolean, last4)
}

// isTransientProviderError inspects error/response and decides if retrying is safe (network timeouts, 5xx where doc says safe)
func isTransientProviderError(err error, res *GatewayResult) bool {
    if err != nil {
        if errors.Is(err, context.DeadlineExceeded) || isNetworkError(err) {
            return true
        }
    }
    if res != nil && res.StatusCode >= 500 && res.StatusCode < 600 {
        // provider 5xx -> transient in most cases
        return true
    }
    return false
}

// isRetryableError is similar but stricter; ensure non-idempotent failures are not retried
func isRetryableError(err error, res *GatewayResult) bool {
    // consult provider capabilities; in our default we only retry on transient provider errors
    return isTransientProviderError(err, res)
}

