func (g *gatewayAdapter) Process(ctx context.Context, req *GatewayRequest, opts ...GatewayOption) (*GatewayResult, error) {
    // Fast-fail if circuit open
    if !g.cb.Allow() {
        return nil, NewApiError("gateway_unavailable", "payment provider unavailable (circuit open)", http.StatusServiceUnavailable)
    }

    baseHeaders := defaultHeaders()
    if req.IdempotencyKey != "" {
        baseHeaders.Set(g.config.IdempotencyHeaderName, req.IdempotencyKey)
    }

    var lastErr error
    for attempt := 1; attempt <= g.config.MaxAttempts; attempt++ {
        // derive per-attempt timeout from parent ctx
        attemptCtx, cancel := context.WithTimeout(ctx, g.config.AttemptTimeout)

        // clone headers per attempt to avoid accidental mutation
        headers := cloneHeader(baseHeaders)

        res, err := g.callProvider(attemptCtx, req, headers)
        // ensure we cancel immediately after the call to avoid leaks
        cancel()

        if err == nil && res != nil && res.Success {
            g.cb.RecordSuccess()
            return res, nil
        }

        // classify error/response
        if isTransientProviderError(err, res) {
            lastErr = err
            g.cb.RecordFailure()
            // backoff with jitter
            sleep := backoffWithJitter(g.config.Backoff, attempt)
            select {
            case <-ctx.Done():
                return nil, ctx.Err()
            case <-time.After(sleep):
                // continue to next attempt
            }
            continue
        }

        // non-transient/permanent error -> record failure and return
        if !isRetryableError(err, res) {
            g.cb.RecordFailure()
            // wrap provider response/error in ApiError (do not leak internals)
            if err != nil {
                return res, NewApiError("gateway_permanent_error", "payment provider rejected the request", http.StatusBadRequest)
            }
            return res, NewApiError("gateway_permanent_error", "payment provider returned error", http.StatusBadRequest)
        }

        // If here and retryable but loop will exit, continue to next iteration
    }

    // exhausted attempts
    if lastErr != nil {
        g.cb.RecordFailure()
        return nil, NewApiError("gateway_retry_exhausted", "payment provider transient errors exhausted", http.StatusBadGateway)
    }
    return nil, NewApiError("gateway_error", "payment provider error", http.StatusBadGateway)
}

