func (s *TransactionService) ProcessTransaction(ctx context.Context, req *ProcessRequest) (*TransactionResult, error) {
    // 1) Claim idempotency entry deterministically
    idemp, err := s.idempRepo.ClaimOrGet(ctx, req.IdempotencyKey, req.CustomerID, s.config.IdempotencyTTL)
    if err != nil {
        s.logger.Warn(ctx, "idempotency claim failed", map[string]interface{}{"err": err})
        return nil, NewApiError("idempotency_error", "failed to create idempotency entry", http.StatusInternalServerError)
    }

    if idemp.Status == IdempotencyStatusDone {
        return idemp.Result, nil
    }

    if idemp.Status == IdempotencyStatusInProgress && !idemp.OwnedByCaller {
        res, err := s.idempRepo.WaitForResult(ctx, idemp.ID, s.config.IdempotencyWaitBackoff)
        if err != nil {
            if errors.Is(err, context.DeadlineExceeded) || errors.Is(err, context.Canceled) {
                return nil, NewApiError("idempotency_wait_timeout", "request in progress; try again", http.StatusAccepted)
            }
            return nil, NewApiError("idempotency_wait_failed", "could not wait for in-progress request", http.StatusInternalServerError)
        }
        return res, nil
    }

    // 2) Create pending transaction (CreatePending must fill txRecord.ID)
    txRecord := &Transaction{CustomerID: req.CustomerID, AmountCents: req.AmountCents, Currency: req.Currency, Status: StatusPending, CreatedAt: time.Now(), IdempotencyKey: req.IdempotencyKey}
    if err := s.repo.CreatePending(ctx, txRecord); err != nil {
        // try mark idempotency failed with concise code
        _ = s.idempRepo.MarkFailed(ctx, idemp.ID, "create_pending_failed")
        return nil, NewApiError("db_error", "failed to create transaction", http.StatusInternalServerError)
    }

    // 3) Call gateway
    gwReq := GatewayRequestFrom(req, txRecord)
    gwRes, gwErr := s.gateway.Process(ctx, gwReq, WithIdempotencyHeader(req.IdempotencyKey))

    // 4) Decide finalStatus and clientResult; defensively handle gwRes==nil
    var finalStatus TransactionStatus
    var clientResult *TransactionResult
    if gwErr == nil && gwRes != nil && gwRes.Success {
        finalStatus = StatusSucceeded
        clientResult = &TransactionResult{TransactionID: txRecord.ID, Status: string(finalStatus), ProviderID: gwRes.ProviderID}
    } else {
        // map gateway error/result to stable api error code
        apiCode := mapGatewayErrorToApiCode(gwErr, gwRes)
        finalStatus = StatusFailed
        clientResult = &TransactionResult{TransactionID: txRecord.ID, Status: string(finalStatus), ErrorCode: apiCode}
    }

    // 5) Optimistic conditional update
    updated, err := s.repo.UpdateStatusIfPending(ctx, txRecord.ID, finalStatus, gwRes)
    if err != nil {
        s.logger.Error(ctx, "status update failed", map[string]interface{}{"tx": txRecord.ID, "err": err})
        _ = s.idempRepo.MarkFailed(ctx, idemp.ID, "update_status_failed")
        return nil, NewApiError("update_failed", "could not finalize transaction", http.StatusInternalServerError)
    }

    if updated == 0 {
        current, rerr := s.repo.GetByID(ctx, txRecord.ID)
        if rerr != nil {
            return nil, NewApiError("read_failed", "could not fetch transaction status", http.StatusInternalServerError)
        }
        clientResult = mapTransactionToResult(current)
        s.logger.Info(ctx, "status update raced; returning canonical", map[string]interface{}{"tx": txRecord.ID, "status": current.Status})
    }

    // 6) Persist idempotency result (StoreResult returns bool if we wrote it)
    if wrote, serr := s.idempRepo.StoreResult(ctx, idemp.ID, clientResult); serr != nil {
        s.logger.Warn(ctx, "failed to persist idempotency result", map[string]interface{}{"idemp": idemp.ID, "err": serr})
    } else if !wrote {
        s.logger.Info(ctx, "idempotency result already present", map[string]interface{}{"idemp": idemp.ID})
    }

    return clientResult, nil
}

