func (r *pgIdempotencyRepo) ClaimOrGet(ctx context.Context, key, customerID string, ttl time.Duration) (*IdempotencyEntry, error) {
    expiry := time.Now().Add(ttl)

    // 1) Try to insert and RETURNING the new row; ON CONFLICT DO NOTHING so conflict -> sql.ErrNoRows
    insertQ := `
INSERT INTO idempotency (idempotency_key, customer_id, status, created_at, ttl)
VALUES ($1, $2, 'IN_PROGRESS', now(), $3)
ON CONFLICT (idempotency_key, customer_id) DO NOTHING
RETURNING id, status, result, created_at, ttl
`
    var e IdempotencyEntry
    var rawResult sql.NullString
    row := r.db.QueryRowContext(ctx, insertQ, key, customerID, expiry)
    if err := row.Scan(&e.ID, &e.Status, &rawResult, &e.CreatedAt, &e.TTL); err == nil {
        if rawResult.Valid {
            _ = json.Unmarshal([]byte(rawResult.String), &e.Result)
        }
        e.OwnedByCaller = true
        return &e, nil
    } else if err != sql.ErrNoRows {
        // real DB error
        return nil, err
    }

    // 2) Insert did nothing (conflict) -> select canonical row deterministically
    selQ := `SELECT id, status, result, created_at, ttl FROM idempotency WHERE idempotency_key = $1 AND customer_id = $2`
    row = r.db.QueryRowContext(ctx, selQ, key, customerID)
    if err := row.Scan(&e.ID, &e.Status, &rawResult, &e.CreatedAt, &e.TTL); err != nil {
        return nil, err
    }
    if rawResult.Valid {
        _ = json.Unmarshal([]byte(rawResult.String), &e.Result)
    }

    // 3) Best-effort extend TTL (warn on failure)
    if expiry.After(e.TTL) {
        if _, err := r.db.ExecContext(ctx, `UPDATE idempotency SET ttl = $1 WHERE id = $2`, expiry, e.ID); err != nil {
            // log TTL extension failure so ops can investigate
            r.logger.Warn(ctx, "idempotency ttl extend failed", map[string]interface{}{"idemp": e.ID, "err": err})
        }
    }

    e.OwnedByCaller = false
    return &e, nil
}

// StoreResult tries to atomically write the DONE/result if this caller owns the IN_PROGRESS entry.
// Returns (wrote, existingResult, error). If another writer already persisted the result, existingResult is populated.
func (r *pgIdempotencyRepo) StoreResult(ctx context.Context, id int64, result *TransactionResult) (bool, *TransactionResult, error) {
    raw, _ := json.Marshal(result)
    query := `UPDATE idempotency SET status = 'DONE', result = $1 WHERE id = $2 AND status = 'IN_PROGRESS' RETURNING status`

    var status string
    if err := r.db.QueryRowContext(ctx, query, raw, id).Scan(&status); err == nil {
        // we wrote the result
        return true, nil, nil
    } else if err == sql.ErrNoRows {
        // someone else already updated or row missing; fetch canonical result
        row := r.db.QueryRowContext(ctx, `SELECT result FROM idempotency WHERE id = $1`, id)
        var rawResult sql.NullString
        if err := row.Scan(&rawResult); err != nil {
            return false, nil, err
        }
        if rawResult.Valid {
            var existing TransactionResult
            if uerr := json.Unmarshal([]byte(rawResult.String), &existing); uerr != nil {
                return false, nil, uerr
            }
            return false, &existing, nil
        }
        // no result stored
        return false, nil, nil
    } else {
        return false, nil, err
    }
}

// MarkFailed sets the idempotency entry to FAILED with a concise internal code; returns error so callers can log failures.
func (r *pgIdempotencyRepo) MarkFailed(ctx context.Context, id int64, internalCode string) error {
    payload, _ := json.Marshal(map[string]string{"internal_code": internalCode})
    query := `UPDATE idempotency SET status = 'FAILED', result = $1 WHERE id = $2 AND status = 'IN_PROGRESS' RETURNING status`
    var status string
    if err := r.db.QueryRowContext(ctx, query, payload, id).Scan(&status); err != nil {
        if err == sql.ErrNoRows {
            // someone else already changed status; not an error for caller
            return nil
        }
        return err
    }
    return nil
}

