func (g *gatewayAdapter) Process(ctx context.Context, req *GatewayRequest, opts ...GatewayOption) (*GatewayResult, error) {
    if !g.cb.Allow() {
        return nil, NewApiError("gateway_unavailable", "payment provider unavailable (circuit open)", http.StatusServiceUnavailable)
    }

    baseHeaders := defaultHeaders()
    if req.IdempotencyKey != "" {
        baseHeaders.Set(g.config.IdempotencyHeaderName, req.IdempotencyKey)
    }

    var lastErr error
    for attempt := 1; attempt <= g.config.MaxAttempts; attempt++ {
        attemptCtx, cancel := context.WithTimeout(ctx, g.config.AttemptTimeout)

        // clone headers to avoid mutation across attempts
        headers := cloneHeader(baseHeaders)

        res, err := g.callProvider(attemptCtx, req, headers)
        // cancel per-attempt context immediately to avoid leaks
        cancel()

        if err == nil && res != nil && res.Success {
            g.cb.RecordSuccess()
            return res, nil
        }

        if isTransientProviderError(err, res) {
            // ensure lastErr is meaningful even when provider responded with 5xx and err == nil
            if err != nil {
                lastErr = err
            } else if res != nil {
                lastErr = fmt.Errorf("provider_transient_status_%d", res.StatusCode)
            }
            g.cb.RecordFailure()

            sleep := backoffWithJitter(g.config.Backoff, attempt)
            select {
            case <-ctx.Done():
                return nil, ctx.Err()
            case <-time.After(sleep):
                continue
            }
        }

        if !isRetryableError(err, res) {
            g.cb.RecordFailure()
            // Map to stable ApiError (do not leak internals). Include correlation id at call site if needed.
            return res, NewApiError("gateway_permanent_error", "payment provider rejected the request", http.StatusBadRequest)
        }
    }

    // exhausted attempts -> include correlation id in message for easier correlation
    if lastErr != nil {
        g.cb.RecordFailure()
        corr := GetCorrelationID(ctx)
        return nil, NewApiError("gateway_retry_exhausted", fmt.Sprintf("payment provider transient errors exhausted (correlation_id=%s)", corr), http.StatusBadGateway)
    }

    corr := GetCorrelationID(ctx)
    return nil, NewApiError("gateway_error", fmt.Sprintf("payment provider error (correlation_id=%s)", corr), http.StatusBadGateway)
}

